cards=[]
for i,g in enumerate(games,1):
    s=next(s for s in sources if s['id']==g['id'])
    imgs=''
    for n,k in enumerate(g['order']):
        im=s['images'][k]
        imgs+=f'''<figure><button class="imagebtn" type="button" aria-label="{html.escape(g['name'])} 이미지 {n+1} 확대"><img src="{image_data(Path(im['path']))}" alt="{html.escape(g['name']+' — '+g['captions'][n])}" loading="lazy"></button><figcaption>{g['captions'][n]} <a href="{html.escape(im['url'])}" target="_blank" rel="noopener">원본</a></figcaption></figure>'''
    cards.append(f'''<article class="game" id="game{g['id']}"><div class="gamehead"><span class="num">0{i}</span><div><p class="eyebrow">{g['tag']}</p><h3>{g['name']}</h3><p class="meta">{g['dev']}</p></div><a class="source" href="{s['url']}" target="_blank" rel="noopener">공식 소개 ↗</a></div><h4>{g['headline']}</h4><div class="gallery">{imgs}</div><div class="analysisgrid"><div><span class="label">확인한 게임 방식</span><p>{g['fact']}</p><span class="label">이미지에서 볼 부분</span><p>{g['visual']}</p></div><div class="propose"><span class="label">공무원 키우기 적용 제안</span><p>{g['apply']}</p><span class="label muted">범위 조절</span><p>{g['boundary']}</p></div></div><p class="sourcefoot">내용 근거: <a href="{s['url']}" target="_blank" rel="noopener">개발사·배급사가 제공한 Steam 공식 제품 소개</a> · 이미지: 같은 제품 페이지의 공개 이미지. 화면 배치에 대한 해석은 이미지 관찰에 기반한다.</p></article>''')

